<script setup lang="ts">
import{ref,onMounted}from'vue';import{api}from'./api';import LoginPage from'../features/LoginPage.vue';import TripList from'../features/TripList.vue';import Workspace from'../features/Workspace.vue';
const user=ref<any>(null),trips=ref<any[]>([]),trip=ref(''),loading=ref(true),error=ref(''),inviteTitle=ref('');const invite=ref(new URLSearchParams(location.hash.slice(1)).get('invite')||'');async function load(){trips.value=await api('/trips')}async function logged(u:any,id?:string){user.value=u;invite.value='';await load();open(id||sessionStorage.getItem('xj-trip:'+u.id)||'')}function open(id:string){trip.value=id;if(user.value)sessionStorage.setItem('xj-trip:'+user.value.id,id)}async function logout(){try{await api('/session','DELETE')}finally{for(const k of Object.keys(sessionStorage))if(k.startsWith('xj-'))sessionStorage.removeItem(k);user.value=null;trip.value=''}}
async function acceptInvite(){try{const r=await api('/invites/accept','POST',{token:invite.value});history.replaceState(null,'',location.pathname);await logged(user.value,r.tripId)}catch(e){error.value=(e as Error).message}}
async function cancelInvite(){invite.value='';history.replaceState(null,'',location.pathname);await logged(user.value)}
onMounted(async()=>{try{const u=await api('/me');if(invite.value){user.value=u;inviteTitle.value=(await api('/invites/preview','POST',{token:invite.value})).title}else await logged(u)}catch(e){if((e as any).status!==401)error.value=(e as Error).message}finally{loading.value=false}});
</script>
<template><div v-if="loading" class="loading-screen">正在打开行间…</div><template v-else><p v-if="error" class="global-error" role="alert">{{error}} <button @click="error=''">关闭</button></p><LoginPage v-if="!user" :invite="invite" @login="logged"/><section v-else-if="invite" class="loading-screen"><h2>一起规划「{{inviteTitle||'旅行'}}」</h2><p>将以 {{user.username}} 的身份加入。</p><button class="primary" :disabled="!inviteTitle" @click="acceptInvite">接受邀请</button><button class="secondary" @click="cancelInvite">暂不加入</button></section><Workspace v-else-if="trip" :key="trip" :trip-id="trip" :user="user" @back="open('');load()" @logout="logout"/><TripList v-else :trips="trips" :user="user" @open="open" @logout="logout"/></template></template>
